  "inlineSchema": "// Este es el archivo \"schema\" de Prisma.\n// Define la conexión a tu base de datos y la estructura de tus tablas.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// --- ENUMS ---\n\nenum Role {\n  USER\n  ADMIN\n}\n\nenum TransactionStatus {\n  INICIADO\n  PAGADO_EN_RETENCION\n  COMPLETADO\n  DISPUTADO\n  CANCELADO\n}\n\nenum ListingType {\n  PRODUCTO\n  SERVICIO\n  INFOPRODUCTO\n}\n\n// Estado del ítem\nenum ProductCondition {\n  NUEVO\n  USADO\n  REACONDICIONADO\n}\n\n// --- MODELOS DE DATOS ---\n\n// 1. Modelo de CATEGORÍAS\nmodel Category {\n  id       String     @id @default(uuid())\n  name     String\n  slug     String     @unique\n  parentId String?\n  parent   Category?  @relation(\"SubCategories\", fields: [parentId], references: [id])\n  children Category[] @relation(\"SubCategories\")\n  products Product[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// 2. Modelo de USUARIO\nmodel User {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  password  String\n  name      String?\n  role      Role     @default(USER)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  products             Product[]\n  services             Service[] // (Legacy)\n  transactionsAsBuyer  Transaction[]        @relation(\"BuyerTransactions\")\n  transactionsAsSeller Transaction[]        @relation(\"SellerTransactions\")\n  ratingsGiven         Rating[]             @relation(\"RaterRatings\")\n  ratingsReceived      Rating[]             @relation(\"RatedRatings\")\n  professionalProfile  ProfessionalProfile?\n\n  // RELACIONES DE PREGUNTAS (NUEVO)\n  questionsAsker Question[] @relation(\"AskerQuestions\") // Preguntas que hice yo\n}\n\n// 3. Modelo de PERFIL PROFESIONAL\nmodel ProfessionalProfile {\n  id              String   @id @default(uuid())\n  user            User     @relation(fields: [userId], references: [id])\n  userId          String   @unique\n  title           String?\n  experienceYears Int?\n  education       String?\n  summary         String?  @db.Text\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n}\n\n// 4. Modelo de PRODUCTO (Publicación)\nmodel Product {\n  id        String @id @default(uuid())\n  creator   User   @relation(fields: [creatorId], references: [id])\n  creatorId String\n\n  category   Category?   @relation(fields: [categoryId], references: [id])\n  categoryId String?\n  type       ListingType @default(PRODUCTO)\n\n  title       String\n  description String   @db.Text\n  price       Float\n  images      String[]\n  status      String   @default(\"DISPONIBLE\") // DISPONIBLE, PAUSADO, SIN_STOCK\n\n  // --- CONTROL DE STOCK (NUEVO) ---\n  stock Int @default(1) // Cantidad disponible\n\n  // Detalles opcionales\n  condition ProductCondition?\n  brand     String?\n  model     String?\n  year      Int?\n  mileage   Int?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  transactions Transaction[]\n\n  // RELACIONES DE PREGUNTAS (NUEVO)\n  questions Question[] // Preguntas recibidas en este producto\n}\n\n// 5. Modelo de SERVICIO (LEGACY)\nmodel Service {\n  id              String   @id @default(uuid())\n  creator         User     @relation(fields: [creatorId], references: [id])\n  creatorId       String\n  title           String\n  description     String   @db.Text\n  price           Float\n  status          String   @default(\"DISPONIBLE\")\n  timesContracted Int      @default(0)\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  transactions Transaction[]\n}\n\n// 6. Modelo de TRANSACCIÓN\nmodel Transaction {\n  id       String @id @default(uuid())\n  buyer    User   @relation(\"BuyerTransactions\", fields: [buyerId], references: [id])\n  buyerId  String\n  seller   User   @relation(\"SellerTransactions\", fields: [sellerId], references: [id])\n  sellerId String\n\n  product   Product? @relation(fields: [productId], references: [id])\n  productId String?\n  service   Service? @relation(fields: [serviceId], references: [id])\n  serviceId String?\n\n  status        TransactionStatus @default(INICIADO)\n  amount        Float\n  platformFee   Float\n  sellerPayout  Float\n  mercadoPagoId String?           @unique\n\n  // CAMPOS DE BORRADO LÓGICO\n  deletedByBuyer  Boolean @default(false)\n  deletedBySeller Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  rating Rating?\n}\n\n// 7. Modelo de CALIFICACIÓN\nmodel Rating {\n  id            String      @id @default(uuid())\n  transaction   Transaction @relation(fields: [transactionId], references: [id])\n  transactionId String      @unique\n\n  rater   User   @relation(\"RaterRatings\", fields: [raterId], references: [id])\n  raterId String\n  rated   User   @relation(\"RatedRatings\", fields: [ratedId], references: [id])\n  ratedId String\n\n  rating  Int\n  comment String? @db.Text\n\n  quality         Int?\n  professionalism Int?\n  communication   Int?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// 8. Modelo de PREGUNTAS (Q&A) - NUEVO\nmodel Question {\n  id      String @id @default(uuid())\n  content String @db.Text // La pregunta del interesado\n\n  answer     String?   @db.Text // La respuesta del vendedor (opcional al inicio)\n  answeredAt DateTime? // Cuándo se respondió\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt // Por si edita la respuesta\n\n  // Relación con el Producto\n  product   Product @relation(fields: [productId], references: [id])\n  productId String\n\n  // Relación con quien Pregunta (Asker)\n  asker   User   @relation(\"AskerQuestions\", fields: [askerId], references: [id])\n  askerId String\n}\n",
